  {
    "type": "function",
    "function": {
      "name": "get_purchase_order",
      "description": "Read a purchase order and its supplier's master data.",
      "parameters": {
        "type": "object",
        "properties": {
          "po_id": {
            "type": "string",
            "description": "Purchase order id, e.g. \"PO-1A2B3C\"."
          },
          "consistent": {
            "type": "boolean",
            "description": "Optional; true reads the primary copy, which always reflects every committed write. The default (false) may be served by a replica that can lag recent writes by a few reads."
          }
        },
        "required": [
          "po_id"
        ]
      },
      "return": {
        "type": "object",
        "additionalProperties": {}
      }
    }
  },
